def length_of_longest_substring(s):
    n = len(s)
    best = 0
    for start in range(n):
        seen = set()
        end = start
        while end < n and s[end] not in seen:
            seen.add(s[end])                                                # extend while this character hasn't been seen in this stretch yet
            end += 1
        best = max(best, end - start)
    return best


if __name__ == "__main__":
    print(length_of_longest_substring("abcabcbb"))

