    left = 0
    best = 0
    for right, c in enumerate(s):
        if c in last_seen and last_seen[c] >= left:
            left = last_seen[c] + 1                                       # jump left straight past the previous occurrence, no crawling needed
        last_seen[c] = right
        best = max(best, right - left + 1)
    return best


