using namespace std;

int lengthOfLongestSubstring(string s) {
    unordered_map<char, int> lastSeen;                                          // maps character -> its most recent index
    int left = 0;
    int best = 0;
    for (int right = 0; right < (int)s.size(); right++) {
        char c = s[right];
        if (lastSeen.count(c) && lastSeen[c] >= left) {
            left = lastSeen[c] + 1;                                              // jump left straight past the previous occurrence, no crawling needed
        }
        lastSeen[c] = right;
        best = max(best, right - left + 1);
    }
    return best;
}

